import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Line } from 'react-chartjs-2';
import logoImage from '../assets/aqi.webp'; 
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
} from 'chart.js';
import { useAuth } from '../App';
import './css/MapPage.css';
import { calculateDistance, formatDistance } from '../utils/distance';

ChartJS.register(
  CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, Filler
);

// --- Helper Functions ---
const getAQIColor = (aqi) => {
    if (aqi === null || aqi === undefined) return '#6b7280'; // Gray - Unknown

    if (aqi <= 50) return '#10b981';   // ✅ Good (Green)
    if (aqi <= 100) return '#84cc16';  // 🙂 Satisfactory (Light Green)
    if (aqi <= 200) return '#facc15';  // 😷 Moderate (Yellow)
    if (aqi <= 300) return '#f97316';  // ⚠️ Poor (Orange)
    if (aqi <= 400) return '#ef4444';  // ☠️ Very Poor (Red)
    
    return '#7c2d12';                  // ☣️ Severe (Dark Maroon)
};


const getAQIStatus = (aqi) => {
    if (aqi === null || aqi === undefined) return 'Unknown';

    if (aqi <= 50) return 'Good';
    if (aqi <= 100) return 'Satisfactory';
    if (aqi <= 200) return 'Moderate';
    if (aqi <= 300) return 'Poor';
    if (aqi <= 400) return 'Very Poor';
    
    return 'Severe';
};


// ...
// Using shared calculateDistance & formatDistance from utils/distance.js
// ..


const createAqiIcon = (aqi, isComingSoon = false, label = '') => {
    const color = isComingSoon ? '#cbd5e1' : getAQIColor(aqi);
    const displayValue = isComingSoon ? '?' : (Math.round(aqi) || 'N/A');

    // Larger, high-contrast icon HTML with subtle border and shadow for clarity
    const iconHtml = `
        <div class="aqi-marker-icon ${isComingSoon ? 'coming-soon' : ''}" style="display:flex;flex-direction:column;align-items:center;">
            <div class="aqi-marker-icon-inner" style="width:56px;height:56px;border-radius:28px;display:flex;align-items:center;justify-content:center;background:${color};color:#fff;font-weight:700;font-size:1rem;box-shadow:0 2px 6px rgba(0,0,0,0.25);border:2px solid #ffffff;">
                ${displayValue}
            </div>
            ${label ? `<div class=\"aqi-marker-label\" style=\"margin-top:4px;font-size:0.75rem;color:#111827;background:rgba(255,255,255,0.9);padding:2px 6px;border-radius:6px;max-width:120px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;text-align:center;\">${label}</div>` : ''}
        </div>
    `;

    // Increase iconSize and anchor to accommodate label
    return window.L.divIcon({ html: iconHtml, className: 'custom-div-icon', iconSize: [64, label ? 84 : 68], iconAnchor: [32, label ? 84 : 68] });
};

// Enhanced popup content creator
const createStationPopupContent = (station, stationId) => {
    // AFTER
    const isRealStation = ['lora-v1', 'loradev2', 'lora-v3'].includes(stationId);
    const isComingSoon = stationId.startsWith('temp-');

    if (isComingSoon) {
        return `
            <div class="map-station-popup coming-soon-popup">
                <div class="popup-header">
                    <div class="popup-station-name">${station.station_info.name}</div>
                    <div class="coming-soon-badge">
                        <span class="coming-soon-icon">🚧</span>
                        <span class="coming-soon-text">Coming Soon</span>
                    </div>
                </div>
                <div class="coming-soon-message">
                    <p>This monitoring station is under development and will be operational soon.</p>
                    <p>Stay tuned for real-time air quality data from this location!</p>
                </div>
            </div>
        `;
    }

    const { station_info, averages, latest_readings, highest_sub_index } = station; // Added latest_readings
    
    // 1. Master list including PM1 and Weather
    const masterPollutants = [
        { key: 'pm25', name: 'PM2.5', unit: 'µg/m³' },
        { key: 'pm10', name: 'PM10', unit: 'µg/m³' },
        { key: 'pm1', name: 'PM1.0', unit: 'µg/m³' },
        { key: 'so2', name: 'SO₂', unit: 'µg/m³' },
        { key: 'no2', name: 'NO₂', unit: 'µg/m³' },
        { key: 'co', name: 'CO', unit: 'µg/m³' },
        { key: 'o3', name: 'O₃', unit: 'µg/m³' },
        { key: 'nh3', name: 'NH₃', unit: 'µg/m³' },
        { key: 'temp', name: 'Temp', unit: '°C' },
        { key: 'humidity', name: 'Humidity', unit: '%' },
        { key: 'pre', name: 'Pressure', unit: 'hPa' }
    ];

    const hasMeasurement = (raw = {}, avg = {}, key) => {
        if (key === 'temp') {
            return raw.temp !== undefined || raw.temperature !== undefined || avg.temp !== undefined || avg.temperature !== undefined;
        }
        if (key === 'humidity') {
            return raw.hum !== undefined || raw.humidity !== undefined || avg.hum !== undefined || avg.humidity !== undefined;
        }
        if (key === 'pre') {
            return raw.pre !== undefined || raw.pressure !== undefined || avg.pre !== undefined || avg.pressure !== undefined;
        }

        return raw[key] !== undefined || avg[key] !== undefined;
    };

    // 2. Dynamically filter out missing sensors using both latest readings and averages
    const activePollutants = masterPollutants.filter(p => {
        const raw = latest_readings || {};
        const avg = averages || {};
        return hasMeasurement(raw, avg, p.key);
    });

    // 3. Generate HTML only for active sensors
    const readingsHtml = activePollutants.map(p => {
        let displayValue = 'N/A';
        const raw = latest_readings || {};
        const avg = averages || {};

        if (p.key === 'temp') {
            displayValue = raw.temp ?? raw.temperature ?? avg.temp ?? avg.temperature ?? 'N/A';
        } else if (p.key === 'humidity') {
            displayValue = raw.hum ?? raw.humidity ?? avg.hum ?? avg.humidity ?? 'N/A';
        } else if (p.key === 'pre') {
            displayValue = raw.pre ?? raw.pressure ?? avg.pre ?? avg.pressure ?? 'N/A';
        } else {
            const value = avg[p.key] ?? raw[p.key];
            displayValue = value !== undefined && value !== null ? Number(value).toFixed(2) : 'N/A';
        }

        return `
            <div class="popup-reading-item">
                <div class="popup-reading-label">${p.name}</div>
                <div class="popup-reading-value">
                    ${displayValue}
                    <span class="popup-reading-unit">${p.unit}</span>
                </div>
            </div>
        `;
    }).join('');

    return `
        <div class="map-station-popup">
            <div class="popup-header">
                <div class="popup-station-name">${station_info.name}</div>
                <div class="popup-aqi-display">
                    <div class="popup-aqi-value" style="background-color: ${getAQIColor(highest_sub_index)}">
                        ${Math.round(highest_sub_index) || 'N/A'}
                    </div>
                    <div class="popup-aqi-status">${getAQIStatus(highest_sub_index)}</div>
                    <div class="real-sensor-badge">🟢 Live Data</div>
                </div>
            </div>
            <div class="popup-readings">
                <div class="popup-readings-title">Current Readings</div>
                <div class="popup-readings-grid">
                    ${readingsHtml}
                </div>
            </div>
            <a href="#" class="popup-view-details" onclick="window.mapPageInstance.handleStationSelect('${stationId}', true); return false;">
                📊 View Detailed Analysis
            </a>
        </div>
    `;
};

// Create popup content for the user's location marker
const createUserPopupContent = (data, isFetching = false) => {
    if (!data) {
        return `
            <div class="user-popup">
                <div style="font-weight:600;">No location data</div>
                <div style="color:#6b7280;font-size:0.9rem">Click the marker or "Find My Location" to get personalized AQI.</div>
            </div>
        `;
    }

    const aqiDisplay = (data.aqi != null && !isNaN(data.aqi)) ? Math.round(data.aqi) : 'N/A';
    const status = getAQIStatus(data.aqi);
    const dist = (data.distance_to_nearest != null) ? formatDistance(data.distance_to_nearest) : 'N/A';

    return `
        <div class="user-popup" style="min-width:200px;">
            <div style="display:flex;align-items:center;gap:10px;">
                <div style="width:48px;height:48px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:${getAQIColor(data.aqi)};color:#fff;font-weight:700;">
                    ${aqiDisplay}
                </div>
                <div style="flex:1;">
                    <div style="font-weight:700">Your AQI ${isFetching ? '<span style=\"font-weight:400;font-size:0.85rem;color:#6b7280;\">(updating…)</span>' : ''}</div>
                    <div style="font-size:0.95rem;color:#374151">${status}</div>
                    <div style="font-size:0.85rem;color:#6b7280;margin-top:4px">Nearest sensor • ${dist}</div>
                </div>
            </div>
        </div>
    `;
};

const MapPage = () => {
    // === STATE MANAGEMENT ===
    const [mapInstance, setMapInstance] = useState(null);
    const [stations, setStations] = useState({});
    const [selectedStationId, setSelectedStationId] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);
    const [forecastData, setForecastData] = useState([]);
    const [isForecastLoading, setIsForecastLoading] = useState(false);
    const [selectedParameter, setSelectedParameter] = useState('pm25_max');
    const [forecastUpdatedAt, setForecastUpdatedAt] = useState(null);
    
    // User location states
    const [userLocation, setUserLocation] = useState(null);
    const [userLocationData, setUserLocationData] = useState(null);
    const [isFetchingUserAqi, setIsFetchingUserAqi] = useState(false);
    const [nearestStation, setNearestStation] = useState(null);
    const [isLocationLoading, setIsLocationLoading] = useState(false);
    
    // Mobile-specific states
    const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
    const [showMobileMenu, setShowMobileMenu] = useState(false);
    const [activeTab, setActiveTab] = useState('stations');
    // NEW: Full screen map state
    const [isFullScreenMap, setIsFullScreenMap] = useState(false);
    const [isBottomSheetCollapsed, setIsBottomSheetCollapsed] = useState(false);

    // Refs
    const mapRef = useRef(null);
    const markersRef = useRef({});
    const userLocationMarkerRef = useRef(null);
    const accuracyCircleRef = useRef(null);
    const locationRequestRef = useRef(false);   // true while a GPS request is running
    const autoLocateTriedRef = useRef(false);   // auto-locate only once per visit
    const [locationError, setLocationError] = useState(null);

    // Hooks
    const navigate = useNavigate();
    const { user, logout, loading: authLoading } = useAuth();
    const _storedUser = (() => { try { return JSON.parse(localStorage.getItem('user') || 'null'); } catch { return null; } })();
    const displayName = user?.username || user?.name || _storedUser?.username || _storedUser?.name || _storedUser?.phone_number || '';
    const [authInitialized, setAuthInitialized] = useState(false);
    const API_BASE_URL = process.env.NODE_ENV === 'production'
  ? 'https://aiiot-1.onrender.com'
  : 'http://localhost:8000';

    // === USER LOCATION TRACKING ===
    // isManual = true when the user taps the crosshair button (always re-centres, shows errors)
    const trackUserLocation = useCallback((isManual = false) => {
        // Prevent overlapping requests (ref, so this callback doesn't change on every request)
        if (locationRequestRef.current) return;

        if (!user) {
            if (isManual) setLocationError('Log in to see the air quality at your location.');
            return;
        }

        if (!navigator.geolocation) {
            setLocationError('Location is not supported by this browser.');
            return;
        }

        locationRequestRef.current = true;
        setIsLocationLoading(true);
        setLocationError(null);

        navigator.geolocation.getCurrentPosition(
            (position) => {
                const loc = {
                    lat: position.coords.latitude,
                    lng: position.coords.longitude,
                    accuracy: position.coords.accuracy, // metres
                    timestamp: Date.now()
                };

                console.log('Location obtained:', loc);
                locationRequestRef.current = false;
                setUserLocation(loc);
                setIsLocationLoading(false);

                if (mapInstance) {
                    const currentCenter = mapInstance.getCenter();
                    const distance = calculateDistance(
                        currentCenter.lat,
                        currentCenter.lng,
                        loc.lat,
                        loc.lng
                    );

                    // Button tap: always go to the user. Auto-locate: only move if >1 km away.
                    if (isManual || distance > 1) {
                        mapInstance.setView([loc.lat, loc.lng], 15);
                    }

                    // Accuracy circle — shows how precise the GPS fix is
                    if (loc.accuracy && loc.accuracy < 5000) {
                        if (accuracyCircleRef.current) {
                            accuracyCircleRef.current.setLatLng([loc.lat, loc.lng]).setRadius(loc.accuracy);
                        } else {
                            accuracyCircleRef.current = window.L.circle([loc.lat, loc.lng], {
                                radius: loc.accuracy,
                                color: '#2563eb',
                                weight: 1,
                                fillColor: '#2563eb',
                                fillOpacity: 0.08,
                                interactive: false
                            }).addTo(mapInstance);
                        }
                    }

                    // Update user marker without recreating
                    const userIcon = window.L.divIcon({
                        html: '<div class="user-location-marker"><i class="fas fa-user"></i></div>',
                        className: 'custom-user-icon',
                        iconSize: [30, 30],
                        iconAnchor: [15, 15]
                    });
                    
                    if (userLocationMarkerRef.current) {
                        userLocationMarkerRef.current.setLatLng([loc.lat, loc.lng]);
                    } else {
                        const marker = window.L.marker([loc.lat, loc.lng], {
                            icon: userIcon,
                            title: 'Your location'
                        }).addTo(mapInstance);

                        // Bind an initial popup (may show "No location data" until backend responds)
                        marker.bindPopup(createUserPopupContent(null, false));

                        // Open popup on click (makes marker interactive)
                        marker.on('click', () => {
                            marker.openPopup();
                        });

                        userLocationMarkerRef.current = marker;
                    }
                }
            },
            (error) => {
                locationRequestRef.current = false;
                setIsLocationLoading(false);
                console.warn('Geolocation error:', error.code, error.message);

                const messages = {
                    1: 'Location permission is blocked. Allow location for this site in your browser settings.',
                    2: 'Your location could not be found. Check that GPS / location services are on.',
                    3: 'Finding your location took too long. Tap the location button to try again.'
                };
                // Auto-locate stays quiet when permission is denied; a button tap always explains.
                if (isManual || error.code !== 1) {
                    setLocationError(messages[error.code] || 'Could not get your location.');
                }
            },
            {
                enableHighAccuracy: true,
                timeout: 15000,     // GPS on phones often needs more than 8 s
                maximumAge: 60000   // reuse a fix up to 1 min old (was 5 min = stale position)
            }
        );
    }, [user, mapInstance]);

    // Hide the location message automatically after a few seconds
    useEffect(() => {
        if (!locationError) return;
        const t = setTimeout(() => setLocationError(null), 6000);
        return () => clearTimeout(t);
    }, [locationError]);

    // Initialize auth state properly
    useEffect(() => {
        // Wait for auth to finish loading before showing UI
        if (!authLoading) {
            setAuthInitialized(true);
        }
    }, [authLoading]);

    // Auto-locate ONCE when the user is logged in and the map is ready.
    // (Before: it re-ran after every failure, so a denied/timed-out request retried every 2 s forever.)
    useEffect(() => {
        if (!user || !mapInstance || userLocation || autoLocateTriedRef.current) return;

        const timer = setTimeout(() => {
            autoLocateTriedRef.current = true;
            trackUserLocation(false);
        }, 1500);

        return () => clearTimeout(timer);
    }, [user, mapInstance, userLocation, trackUserLocation]);
    
    // Make component instance available globally for popup callbacks
    useEffect(() => {
        window.mapPageInstance = {
            handleStationSelect: (stationId, fromPopup = false) => {
                // Only allow selection of real stations
                
                if (['lora-v1', 'loradev2', 'lora-v3', 'lora-v4','lora-v5'].includes(stationId)) {
                    setSelectedStationId(stationId);
                    if (isMobile) {
                        setActiveTab('details');
                        setShowMobileMenu(true);
                        setIsBottomSheetCollapsed(false);
                    }
                    if (fromPopup && mapInstance && stations[stationId]) {
                        const { lat, lng } = stations[stationId].station_info;
                        mapInstance.setView([lat, lng], 15);
                    }
                }
            }
        };
        return () => {
            delete window.mapPageInstance;
        };
    }, [mapInstance, stations, isMobile]);

    // === RESPONSIVE DETECTION ===
    useEffect(() => {
        const handleResize = () => {
            const width = window.innerWidth;
            setIsMobile(width <= 768);
        };

        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // === MAP INITIALIZATION ===
    useEffect(() => {
        let map;
        if (mapRef.current && !mapRef.current._leaflet_id) {
            map = window.L.map(mapRef.current, { 
                zoomControl: false,
                attributionControl: true
            }).setView([10.176, 76.430], 13);
            
            window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                attribution: '© OpenStreetMap contributors',
                className: 'map-tiles'
            }).addTo(map);
            
            window.L.control.zoom({ position: 'topleft' }).addTo(map);
            setMapInstance(map);
        }
        return () => { if (map) map.remove(); };
    }, []);
            
    // --- DELETED `calculateIDWInterpolation` function ---
    
    // === DATA FETCHING - CORRECTED ===
    const fetchRealtimeData = useCallback(async () => {
        setIsLoading(true);
        try {
            // *** URL FIX: Added /api/ prefix ***
            const response = await fetch(`${API_BASE_URL}/api/map/realtime/`);
            if (!response.ok) throw new Error('Failed to fetch data');
            
            // --- Robust JSON Check ---
            const contentType = response.headers.get("content-type");
            if (!contentType || !contentType.includes("application/json")) {
                throw new TypeError(`Expected JSON from /api/map/realtime/ but got HTML. Check your ROOT urls.py file.`);
            }
            
            const data = await response.json();
            
            const processedStations = {};
            
            // Add real stations with data
            if (data.stations['lora-v1']) {
                processedStations['lora-v1'] = data.stations['lora-v1'];
            }
            if (data.stations['loradev2']) {
                processedStations['loradev2'] = data.stations['loradev2'];
            }
            if (data.stations['lora-v3']) {
                processedStations['lora-v3'] = data.stations['lora-v3'];
            }
            if (data.stations['lora-v4']) {
                processedStations['lora-v4'] = data.stations['lora-v4'];
            }
            if (data.stations['lora-v5']) {
                processedStations['lora-v5'] = data.stations['lora-v5'];
            }
            // Add coming soon stations (location only)
            ['temp-3'].forEach(id => {
                if (data.stations[id]) {
                    processedStations[id] = {
                        station_info: data.stations[id].station_info,
                        averages: null,
                        highest_sub_index: null,
                        is_coming_soon: true
                    };
                }
            });
            
            setStations(processedStations);
            
            // Set default selection to first real station
            if (!selectedStationId) {
                const realStations = Object.keys(processedStations).filter(id => !id.startsWith('temp-'));
                if (realStations.length > 0) {
                    setSelectedStationId(realStations[0]);
                }
            }
        } catch (err) {
            setError(err.message);
        } finally {
            setIsLoading(false);
        }
    }, [API_BASE_URL, selectedStationId]);

    useEffect(() => {
        fetchRealtimeData();
        const interval = setInterval(fetchRealtimeData, 30000);
        return () => clearInterval(interval);
    }, [fetchRealtimeData]);

    
    // --- *** THIS IS THE MAIN FIX *** ---
    // === REPLACED USER LOCATION DATA CALCULATION ===
    // This now calls your backend instead of doing math
    
    useEffect(() => {
        // Only run if we have a location AND stations
        if (userLocation && Object.keys(stations).length > 0) {
            console.log('🔍 MapPage: Fetching user-specific AQI from backend...');
            
            const fetchUserAqi = async () => {
                try {
                    setIsFetchingUserAqi(true);
                    // Call the new backend endpoint
                    const aqiResponse = await fetch(`${API_BASE_URL}/api/user-aqi/?lat=${userLocation.lat}&lng=${userLocation.lng}`);
                    
                    if (!aqiResponse.ok) throw new Error(`Failed to fetch user AQI: ${aqiResponse.status}`);
                    const aqiContentType = aqiResponse.headers.get("content-type");
                    if (!aqiContentType || !aqiContentType.includes("application/json")) {
                        throw new TypeError(`Expected JSON from /api/user-aqi/ but got HTML.`);
                    }

                    const aqiData = await aqiResponse.json();
                    console.log("✅ MapPage: Got personalized AQI:", aqiData.user_aqi);

                    // Set state with the data from the backend
                    setUserLocationData({
                        method: 'location_interpolation',
                        source: 'interpolated',
                        aqi: aqiData.user_aqi,
                        station_name: `Your Location`,
                        is_interpolated: true,
                        distance_to_nearest: aqiData.closest_sensor.distance_km,
                        nearest_station_name: aqiData.closest_sensor.sensor_id,
                        values: {} // API currently only returns AQI
                    });

                    setNearestStation({
                        id: aqiData.closest_sensor.sensor_id,
                        distance: aqiData.closest_sensor.distance_km,
                    });
                } catch (err) {
                    console.error("Failed to fetch user AQI, falling back to nearest station.", err);
                    // don't clear existing userLocationData here; keep previous value until a new one arrives
                } finally {
                    setIsFetchingUserAqi(false);
                }
            };

            fetchUserAqi();
        }
    }, [userLocation, stations, API_BASE_URL]); // Removed calculateIDWInterpolation


    // Update the user location marker popup whenever personalized AQI or fetching state changes
    useEffect(() => {
        const marker = userLocationMarkerRef.current;
        if (!marker) return;

        const content = createUserPopupContent(userLocationData, isFetchingUserAqi);
        try {
            if (marker.getPopup && marker.getPopup()) {
                marker.getPopup().setContent(content);
            } else {
                marker.bindPopup(content);
            }
        } catch (err) {
            console.warn('Failed to update user marker popup:', err);
        }
    }, [userLocationData, isFetchingUserAqi]);
    
    
    // === FORECAST DATA FETCHING - URL FIX ===
    useEffect(() => {
        if (!selectedStationId || selectedStationId.startsWith('temp-')) return;
        
        const fetchForecast = async () => {
            setIsForecastLoading(true);
            try {
                // *** URL FIX: Added /api/ prefix ***
                const response = await fetch(`${API_BASE_URL}/api/station/${selectedStationId}/forecast/`);
                if (!response.ok) throw new Error('Failed to fetch forecast');

                const contentType = response.headers.get("content-type");
                if (!contentType || !contentType.includes("application/json")) {
                    throw new TypeError(`Expected JSON from /api/station/.../forecast/ but got HTML.`);
                }
                
                const data = await response.json();
                setForecastData(data.forecast_data || []);
                setForecastUpdatedAt(data.forecast_updated_at || null);
            } catch (err) {
                console.error("Forecast fetch error:", err);
                setForecastData([]);
            } finally {
                setIsForecastLoading(false);
            }
        };
        
        fetchForecast();
    }, [selectedStationId, API_BASE_URL]);

    // === MAP MARKERS UPDATE WITH ENHANCED POPUPS ===
    useEffect(() => {
        if (!mapInstance || Object.keys(stations).length === 0) return;
        
        Object.values(markersRef.current).forEach(marker => marker.remove());
        markersRef.current = {};

        Object.entries(stations).forEach(([id, station]) => {
            const { lat, lng } = station.station_info;
            const isComingSoon = station.is_coming_soon;
            
            const marker = window.L.marker([lat, lng], { 
                icon: createAqiIcon(station.highest_sub_index, isComingSoon) 
            }).addTo(mapInstance);
            
            // Enhanced popup with different content for coming soon vs real stations
            const popupContent = createStationPopupContent(station, id);
            marker.bindPopup(popupContent, {
                maxWidth: 300,
                className: isComingSoon ? 'coming-soon-popup' : 'real-station-popup'
            });
            
            marker.on('click', () => {
                if (isComingSoon) {
                    // Show coming soon message
                    alert(`${station.station_info.name} is coming soon! This station is under development.`);
                } else {
                    setSelectedStationId(id);
                    if (isMobile) {
                        setActiveTab('details');
                        setShowMobileMenu(true);
                        setIsBottomSheetCollapsed(false);
                    }
                    mapInstance.setView([lat, lng], 15);
                }
            });
            
            markersRef.current[id] = marker;
        });
    }, [mapInstance, stations, isMobile]);

    // *** THIS IS THE RESPONSIVENESS FIX ***
    // === MAP RESIZE HANDLER ===
    useEffect(() => {
        if (!mapInstance) return;

        // Use a timeout to ensure the DOM has finished resizing
        // This is crucial for CSS transitions to complete
        const timer = setTimeout(() => {
            console.log('Refreshing map size...');
            mapInstance.invalidateSize();
        }, 400); // 400ms delay

        // Cleanup the timer if the component re-renders
        return () => clearTimeout(timer);
        
    // Re-run this effect anytime a layout state variable changes
    }, [mapInstance, isMobile, isFullScreenMap, isBottomSheetCollapsed]);


    // === EVENT HANDLERS ===
    const handleLogout = useCallback(() => {
        logout();
        setUserLocation(null);
        setUserLocationData(null);
        setNearestStation(null);
        if (userLocationMarkerRef.current) {
            userLocationMarkerRef.current.remove();
            userLocationMarkerRef.current = null;
        }
        if (accuracyCircleRef.current) {
            accuracyCircleRef.current.remove();
            accuracyCircleRef.current = null;
        }
        autoLocateTriedRef.current = false;
    }, [logout]);

    const handleStationSelect = useCallback((stationId) => {
        // Only allow selection of real stations
        // AFTER
        if (['lora-v1', 'loradev2', 'lora-v3', 'lora-v4','lora-v5'].includes(stationId)) {
            setSelectedStationId(stationId);
            if (isMobile) {
                setActiveTab('details');
                setIsBottomSheetCollapsed(false);
            }
        } else {
            // Show coming soon message for temp stations
            const station = stations[stationId];
            if (station) {
                alert(`${station.station_info.name} is coming soon! This station is under development and will be operational soon.`);
            }
        }
    }, [isMobile, stations]);

    // NEW: Handle full screen toggle
    const toggleFullScreenMap = useCallback(() => {
        setIsFullScreenMap(!isFullScreenMap);
        if (!isFullScreenMap) {
            // Going to full screen
            setShowMobileMenu(false);
        }
    }, [isFullScreenMap]);

    // NEW: Handle bottom sheet collapse
    const toggleBottomSheetCollapse = useCallback(() => {
        setIsBottomSheetCollapsed(!isBottomSheetCollapsed);
    }, [isBottomSheetCollapsed]);

    // === DATA PROCESSING ===
    const selectedStationData = stations[selectedStationId];
    const pollutants = [
        { key: 'pm25', name: 'PM2.5', unit: 'µg/m³' },
        { key: 'pm10', name: 'PM10', unit: 'µg/m³' },
        { key: 'so2', name: 'SO₂', unit: 'µg/m³' },
        { key: 'no2', name: 'NO₂', unit: 'µg/m³' },
        { key: 'co', name: 'CO', unit: 'µg/m³' },
        { key: 'o3', name: 'O₃', unit: 'µg/m³' },
        { key: 'nh3', name: 'NH₃', unit: 'µg/m³' },
        { key: 'temp', name: 'Temperature', unit: '°C' },
        { key: 'humidity', name: 'Humidity', unit: '%' }, // New
        { key: 'pre', name: 'Pressure', unit: 'hPa' },
    ];

    const hasMeasurement = (raw = {}, avg = {}, key) => {
        if (key === 'temp') {
            return raw.temp !== undefined || raw.temperature !== undefined || avg.temp !== undefined || avg.temperature !== undefined;
        }
        if (key === 'humidity') {
            return raw.hum !== undefined || raw.humidity !== undefined || avg.hum !== undefined || avg.humidity !== undefined;
        }
        if (key === 'pre') {
            return raw.pre !== undefined || raw.pressure !== undefined || avg.pre !== undefined || avg.pressure !== undefined;
        }

        return raw[key] !== undefined || avg[key] !== undefined;
    };

    // 2. Dynamically filter to only show cards for data the sensor actually sends
    const activePollutants = selectedStationData
        ? pollutants.filter(p => {
            const raw = selectedStationData.latest_readings || {};
            const avg = selectedStationData.averages || {};
            return hasMeasurement(raw, avg, p.key);
        })
        : [];

    // 3. Helper function to safely get the correct display value
    const getDisplayValue = (key) => {
        if (!selectedStationData) return 'N/A';
        const raw = selectedStationData.latest_readings || {};
        const avg = selectedStationData.averages || {};

        if (key === 'temp') return raw.temp ?? raw.temperature ?? avg.temp ?? avg.temperature ?? 'N/A';
        if (key === 'humidity') return raw.hum ?? raw.humidity ?? avg.hum ?? avg.humidity ?? 'N/A';
        if (key === 'pre') return raw.pre ?? raw.pressure ?? avg.pre ?? avg.pressure ?? 'N/A';

        const value = avg[key] ?? raw[key];
        return value !== undefined && value !== null ? Number(value).toFixed(2) : 'N/A';
    };

    // === FORECAST CHART CONFIGURATION ===
    const forecastChartData = useMemo(() => {
        if (!forecastData || forecastData.length === 0) return { labels: [], datasets: [] };
        
        const labels = forecastData.map(d => 
            new Date(d.day).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
        );
        // Round every point to 2 decimals
        const dataPoints = forecastData.map(d => {
            const v = Number(d[selectedParameter]);
            return Number.isFinite(v) ? Math.round(v * 100) / 100 : null;
        });
        
        return { 
            labels, 
            datasets: [{
                label: selectedParameter.replace('_max', '').toUpperCase(),
                data: dataPoints,
                borderColor: '#3b82f6',
                backgroundColor: 'rgba(59, 130, 246, 0.1)',
                fill: true,
                tension: 0.4,
                pointBackgroundColor: '#3b82f6',
                pointBorderColor: '#ffffff',
                pointBorderWidth: 2,
                pointRadius: isMobile ? 4 : 6,
            }]
        };
    }, [forecastData, selectedParameter, isMobile]);

    // Y-axis: start at 0, step is a "nice" number never smaller than 0.01,
    // so a flat line (e.g. all 0.02) doesn't zoom into 0.0190–0.0210.
    const forecastYAxis = useMemo(() => {
        const values = (forecastChartData.datasets[0]?.data || []).filter(v => v !== null);
        const maxVal = values.length ? Math.max(...values, 0) : 0;

        const niceStep = (x) => {
            if (x <= 0.01) return 0.01;
            const p = Math.pow(10, Math.floor(Math.log10(x)));
            const n = x / p;
            const m = n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10;
            return Math.max(0.01, m * p);
        };

        const step = niceStep(maxVal / 4);
        let max = Math.ceil(maxVal / step) * step;
        if (max <= maxVal) max += step;           // headroom so the line isn't on the top edge
        return { min: 0, max: Math.round(max * 100) / 100, step };
    }, [forecastChartData]);

    const formatTwo = (v) => (v === null || v === undefined || isNaN(v) ? '--' : Number(v).toFixed(2));

    const forecastChartOptions = useMemo(() => ({
        responsive: true,
        maintainAspectRatio: false,
        plugins: { 
            legend: { display: false },
            tooltip: {
                backgroundColor: 'rgba(255, 255, 255, 0.95)',
                titleColor: '#1f2937',
                bodyColor: '#374151',
                borderColor: '#d1d5db',
                borderWidth: 1,
                cornerRadius: 8,
                callbacks: {
                    label: (ctx) => `${ctx.dataset.label}: ${formatTwo(ctx.parsed.y)}`
                }
            }
        },
        scales: { 
            x: { 
                ticks: { 
                    color: '#6b7280', 
                    font: { size: isMobile ? 10 : 12 } 
                },
                grid: { color: '#f3f4f6' }
            }, 
            y: { 
                min: forecastYAxis.min,
                max: forecastYAxis.max,
                ticks: { 
                    color: '#6b7280', 
                    font: { size: isMobile ? 10 : 12 },
                    stepSize: forecastYAxis.step,
                    callback: (value) => formatTwo(value)
                },
                grid: { color: '#f3f4f6' }
            } 
        },
        elements: {
            point: {
                hoverRadius: isMobile ? 6 : 8
            }
        }
    }), [isMobile, forecastYAxis]);

    // Filter real stations vs coming soon stations
    const realStations = Object.entries(stations).filter(([id, station]) => !station.is_coming_soon);
    const comingSoonStations = Object.entries(stations).filter(([id, station]) => station.is_coming_soon);

    // Mobile Tab Content Renderer
    const renderMobileTabContent = () => {
        switch (activeTab) {
            case 'stations':
                return (
                    <div className="mobile-tab-content">
                        <div className="mobile-section">
                            <div className="section-header">
                                <h3><i className="fas fa-broadcast-tower"></i> Live Stations</h3>
                                <span className="live-indicator">🔴 LIVE</span>
                            </div>
                            
                            {isLoading ? (
                                <div className="mobile-loader">
                                    <div className="loading-spinner"></div>
                                    <p>Loading stations...</p>
                                </div>
                            ) : error ? (
                                <div className="mobile-error">
                                    <i className="fas fa-exclamation-triangle"></i>
                                    <p>Error: {error}</p>
                                    <button onClick={fetchRealtimeData} className="retry-btn">please refresh.</button>
                                </div>
                            ) : (
                                <div className="station-grid">
                                    {realStations.map(([id, station]) => (
                                        <button 
                                            key={id} 
                                            className={`station-card ${selectedStationId === id ? 'active' : ''}`} 
                                            onClick={() => handleStationSelect(id)}
                                        >
                                            <div className="station-header">
                                                <h4>{station.station_info.name}</h4>
                                                <div className="live-badge">🟢 LIVE</div>
                                            </div>
                                            <div className="station-aqi-badge" style={{ backgroundColor: getAQIColor(station.highest_sub_index) }}>
                                                <span className="aqi-number">{Math.round(station.highest_sub_index) || 'N/A'}</span>
                                                <span className="aqi-status">{getAQIStatus(station.highest_sub_index)}</span>
                                            </div>
                                        </button>
                                    ))}
                                </div>
                            )}
                        </div>

                        <div className="mobile-section">
                            <div className="section-header">
                                {/* <h3><i className="fas fa-clock"></i> Coming Soon</h3> */}
                                {/* <span className="coming-soon-count">{comingSoonStations.length} stations</span> */}
                            </div>
                            
                            <div className="coming-soon-grid">
                                {comingSoonStations.map(([id, station]) => (
                                    <div key={id} className="coming-soon-card" onClick={() => handleStationSelect(id)}>
                                        <div className="station-header">
                                            <h4>{station.station_info.name}</h4>
                                            <div className="coming-soon-badge">🚧 Soon</div>
                                        </div>
                                        <div className="coming-soon-info">
                                            <span>Under Development</span>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                );

            case 'details':
                return (
                    <div className="mobile-tab-content">
                        {selectedStationData && !selectedStationData.is_coming_soon ? (
                            <>
                                <div className="mobile-section-header">
                                    <div className="station-title">
                                        <h3><i className="fas fa-chart-bar"></i> {selectedStationData.station_info.name}</h3>
                                        <div className="live-badge">🟢 LIVE</div>
                                    </div>
                                    <div className="mobile-aqi-display">
                                        <span 
                                            className="mobile-aqi-value"
                                            style={{ backgroundColor: getAQIColor(selectedStationData.highest_sub_index) }}
                                        >
                                            {Math.round(selectedStationData.highest_sub_index)}
                                        </span>
                                        <span className="mobile-aqi-status">
                                            {getAQIStatus(selectedStationData.highest_sub_index)}
                                        </span>
                                    </div>
                                </div>

                                {/* Current Readings */}
                                <div className="mobile-readings-section">
                                    <h4><i className="fas fa-thermometer-half"></i> Current Readings</h4>
                                    <div className="mobile-readings-grid">
                                    {activePollutants.map(p => (
                                        <div className="mobile-reading-card" key={p.key}>
                                            <div className="reading-label">{p.name}</div>
                                            <div className="reading-value">
                                                {getDisplayValue(p.key)}
                                                <span>{p.unit}</span>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                                </div>

                                {/* Forecast */}
                                <div className="mobile-forecast-section">
                                    <div className="forecast-header">
                                        <h4><i className="fas fa-chart-line"></i> 4-Day Forecast</h4>
                                        <select 
                                            className="mobile-parameter-selector"
                                            value={selectedParameter}
                                            onChange={(e) => setSelectedParameter(e.target.value)}
                                        >
                                            <option value="pm25_max">PM2.5</option>
                                            <option value="pm10_max">PM10</option>
                                            <option value="so2_max">SO₂</option>
                                            <option value="no2_max">NO₂</option>
                                            <option value="co_max">CO</option>
                                            <option value="o3_max">O₃</option>
                                            <option value="nh3_max">NH₃</option>
                                        </select>
                                    </div>
                                    
                                    <div className="mobile-chart-container">
                                        {isForecastLoading ? (
                                            <div className="chart-loader">
                                                <div className="loading-spinner small"></div>
                                                <p>Loading forecast...</p>
                                            </div>
                                        ) : forecastData.length > 0 ? (
                                            <Line data={forecastChartData} options={forecastChartOptions} />
                                        ) : (
                                            <div className="no-data-message">
                                                <i className="fas fa-chart-line"></i>
                                                <p>No forecast data available</p>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </>
                        ) : (
                            <div className="mobile-no-selection">
                                <i className="fas fa-satellite-dish"></i>
                                <h3>Select a Live Station</h3>
                                <p>Choose a monitoring station with live data to view detailed information</p>
                                <button 
                                    className="select-station-btn"
                                    onClick={() => setActiveTab('stations')}
                                >
                                    <i className="fas fa-broadcast-tower"></i>
                                    View Live Stations
                                </button>
                            </div>
                        )}
                    </div>
                );

            case 'user':
                return (
                    <div className="mobile-tab-content">
                        <div className="mobile-section-header">
                            <h3><i className="fas fa-map-marker-alt"></i> Your Location Data</h3>
                        </div>
                        
                        {user ? (
                            userLocation && userLocationData && nearestStation ? (
                                <div className="mobile-user-data">
                                    <div className="mobile-user-aqi">
                                        <div 
                                            className="user-aqi-circle"
                                            style={{ backgroundColor: getAQIColor(userLocationData.aqi) }}
                                        >
                                            <span className="aqi-number">{Math.round(userLocationData.aqi)}</span>
                                            <span className="aqi-label">AQI</span>
                                        </div>
                                        <div className="user-location-info">
                                            <div className="location-method">
                                                {userLocationData.is_interpolated ? 
                                                    '🎯 Calculated for your location' : 
                                                    `📍 From ${userLocationData.station_name}`
                                                }
                                            </div>
                                            
                                            <div className="distance-info">
                                                {/* This check prevents the crash */}
                                                {nearestStation && nearestStation.distance != null ? (
                                                    `📏 ${formatDistance(nearestStation.distance)} from nearest sensor`
                                                ) : (
                                                    '📏 Calculating distance...'
                                                )}
                                            </div>
                                            {userLocationData.distance_warning && (
                                                <div className="distance-warning">
                                                    ⚠️ {userLocationData.distance_warning}
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                    
                                    {/* User's readings */}
                                     <div className="mobile-readings-section">
                                        {/* <h4><i className="fas fa-user-circle"></i> Your Air Quality</h4>
                                        <div className="mobile-readings-grid">
                                           
                                            {pollutants
                                            .filter(p => p.key !== 'temp' && p.key !== 'pre' && p.key !== 'humidity') 
                                            .map(p => (
                                            <div className="mobile-reading-card user-reading" key={p.key}>
                                                    <div className="reading-label">{p.name}</div>
                                                    <div className="reading-value">
                                                        {(userLocationData.values?.[p.key]?.toFixed(2)) ?? 'N/A'}
                                                        <span>µg/m³</span>
                                                    </div>
                                                    <div className="data-source-badge">
                                                        {userLocationData.is_interpolated ? '🎯' : '📍'}
                                                    </div>
                                                </div>
                                            ))}
                                        </div> */}
                                    </div> 
                                </div>
                            ) : (
                                <div className="mobile-location-prompt">
                                    <div className="location-prompt-content">
                                        <i className="fas fa-map-marker-alt location-icon"></i>
                                        <h4>Get Your Air Quality Data</h4>
                                        <p>Enable location to see personalized air quality data calculated from our real sensors</p>
                                        <button 
                                            className="mobile-location-btn"
                                            onClick={() => trackUserLocation(true)}
                                            disabled={isLocationLoading}
                                        >
                                            {isLocationLoading ? (
                                                <>
                                                    <i className="fas fa-spinner fa-spin"></i>
                                                    Getting Location...
                                                </>
                                            ) : (
                                                <>
                                                    <i className="fas fa-crosshairs"></i>
                                                    Get My Location
                                                </>
                                            )}
                                        </button>
                                    </div>
                                </div>
                            )
                        ) : (
                            <div className="mobile-login-prompt">
                                <div className="login-prompt-content">
                                    <i className="fas fa-lock login-icon"></i>
                                    <h4>Login Required</h4>
                                    <p>Login to view personalized AQI data for your location</p>
                                    <Link to="/login" className="mobile-login-btn">
                                        <i className="fas fa-sign-in-alt"></i>
                                        Login Now
                                    </Link>
                                </div>
                            </div>
                        )}
                    </div>
                );

            default:
                return null;
        }
    };

    return (
        <div className="map-page">
            {/* Optimized Navbar */}
            <nav className="navbar">
                <div className="navbar-content">
                    <Link to="/" className="navbar-brand">
                        <img src={logoImage} alt="AQM Logo" width={isMobile ? "28" : "36"} height={isMobile ? "28" : "36"} />
                        <span>AirAware</span>
                    </Link>
                    
                    {!isMobile && (
                        <div className="nav-center">
                            <ul className="nav-links">
                                <li><Link to="/homepage" className="nav-link">🏠 Home</Link></li>
                                <li><Link to="/map" className="nav-link active">Live Map</Link></li>
                                {user && (
                                    <>
                                       <li><Link to="/dashboard" className="nav-link">Dashboard</Link></li>
                                    </>
                                )}
                            </ul>
                        </div>
                    )}

                    <div className="nav-right">
    {isMobile && (
        <Link to="/homepage" className="mobile-home-btn" title="Home">
            <i className="fas fa-home"></i>
        </Link>
    )}
    {user ? (
        <div className="user-menu">
            {!isMobile && (
                <div className="user-info">
                    <div className="user-avatar">
                        <i className="fas fa-user"></i>
                    </div>
                    <span className="user-name">{displayName}</span>
                </div>
            )}
            <button onClick={handleLogout} className="logout-btn">
                <i className="fas fa-sign-out-alt"></i>
                {!isMobile && 'Logout'}
            </button>
        </div>
    ) : (
        <Link to="/login" className="login-btn">
            <i className="fas fa-sign-in-alt"></i>
            {!isMobile && 'Login'}
        </Link>
    )}
</div>
                </div>
            </nav>

            {/* Main Content */}
            <div className="main-content">
                {/* Map Container */}
                <div className={`map-container ${isFullScreenMap ? 'full-screen' : ''}`}>
                    <div id="map" ref={mapRef} className="map-element"></div>
                    
                    {/* Map Controls */}
                    {locationError && (
                        <div className="location-toast" role="status">
                            <i className="fas fa-location-crosshairs"></i>
                            <span>{locationError}</span>
                            <button onClick={() => setLocationError(null)} aria-label="Dismiss">×</button>
                        </div>
                    )}

                    <button
                        onClick={() => trackUserLocation(true)}
                        className={`my-location-btn ${isLocationLoading ? 'loading' : ''}`}
                        title="Find My Location"
                        disabled={isLocationLoading}
                    >
                        {isLocationLoading ? (
                            <i className="fas fa-spinner fa-spin"></i>
                        ) : (
                            <i className="fas fa-crosshairs"></i>
                        )}
                    </button>

                    {/* NEW: Mobile Map Controls */}
                    {isMobile && (
                        <div className="mobile-map-controls">
                            {/* Full Screen Toggle */}
                            <button 
                                className="mobile-control-btn full-screen-btn"
                                onClick={toggleFullScreenMap}
                                title={isFullScreenMap ? "Exit Full Screen" : "Full Screen Map"}
                            >
                                <i className={`fas ${isFullScreenMap ? 'fa-compress' : 'fa-expand'}`}></i>
                            </button>

                            {/* Menu Toggle (only show when not in full screen) */}
                            {!isFullScreenMap && (
                                <button 
                                    className="mobile-control-btn menu-toggle-btn"
                                    onClick={() => setShowMobileMenu(!showMobileMenu)}
                                    title="Toggle Menu"
                                >
                                    <i className={`fas ${showMobileMenu ? 'fa-times' : 'fa-bars'}`}></i>
                                </button>
                            )}

                            {/* Quick Exit Full Screen Overlay */}
                            {isFullScreenMap && (
                                <button 
                                    className="full-screen-exit-overlay"
                                    onClick={toggleFullScreenMap}
                                >
                                    <i className="fas fa-compress"></i>
                                    <span>Exit Full Screen</span>
                                </button>
                            )}
                        </div>
                    )}
                </div>

                {/* Desktop Layout */}
                {!isMobile && (
                    <>
                        {/* LEFT PANEL - Optimized */}
                        <div className="sidebar-panel">
                            <div className="panel-content">
                                {/* User Location Panel - Optimized */}
                                {user && userLocation && userLocationData && nearestStation && (
                                    <div className="user-location-section">
                                        <div className="section-title">
                                            <i className="fas fa-map-marker-alt"></i>
                                            <span>Your Location</span>
                                        </div>
                                        <div className="user-aqi-card">
                                            <div className="user-aqi-main">
                                                <div className="aqi-circle" style={{ backgroundColor: getAQIColor(userLocationData.aqi) }}>
                                                    <span className="aqi-value">{Math.round(userLocationData.aqi)}</span>
                                                    <span className="aqi-label">AQI</span>
                                                    {isFetchingUserAqi && (
                                                        <span className="aqi-refresh-indicator" title="Updating...">
                                                            <i className="fas fa-spinner fa-spin" style={{ marginLeft: 8, fontSize: '0.8rem' }}></i>
                                                        </span>
                                                    )}
                                                </div>
                                                <div className="location-details">
                                                    <div className="location-status">
                                                        {userLocationData.is_interpolated ? 
                                                            '🎯 Calculated for your exact location' : 
                                                            `📍 From ${userLocationData.nearest_station_name}`
                                                        }
                                                    </div>
                                                    <div className="distance-info">
                                                        📏 {formatDistance(nearestStation.distance)} from nearest sensor
                                                    </div>
                                                </div>
                                            </div>
                                            
                                            {/* Quick readings */}
                                            
                                        </div>
                                    </div>
                                )}

                               
                                {/* Station List - Optimized */}
                                <div className="stations-section">
                                    <div className="section-title">
                                        <i className="fas fa-broadcast-tower"></i>
                                        <span>Live Monitoring Stations</span>
                                        <div className="live-indicator">🔴 LIVE</div>
                                    </div>
                                    
                                    {isLoading ? (
                                        <div className="section-loader">
                                            <div className="loading-spinner"></div>
                                            <p>Loading stations...</p>
                                        </div>
                                    ) : error ? (
                                        <div className="section-error">
                                            <i className="fas fa-exclamation-triangle"></i>
                                            <p>Error: {error}</p>
                                            <button onClick={fetchRealtimeData} className="retry-btn">
                                                <i className="fas fa-redo"></i>
                                                Retry
                                            </button>
                                        </div>
                                    ) : (
                                        <>
                                            <div className="station-list">
                                                {realStations.map(([id, station]) => (
                                                    <button 
                                                        key={id} 
                                                        className={`station-item ${selectedStationId === id ? 'active' : ''}`} 
                                                        onClick={() => handleStationSelect(id)}
                                                    >
                                                        <div className="station-content">
                                                            <div className="station-name">
                                                                {station.station_info.name}
                                                                <span className="live-dot">🟢</span>
                                                            </div>
                                                            <div 
                                                                className="station-aqi" 
                                                                style={{ backgroundColor: getAQIColor(station.highest_sub_index) }}
                                                            >
                                                                {Math.round(station.highest_sub_index) || 'N/A'}
                                                            </div>
                                                        </div>
                                                    </button>
                                                ))}
                                            </div>
                                            
                                            {/* Coming Soon Stations */}
                                            <div className="coming-soon-section">
                                                {/* <div className="section-subtitle">
                                                    <i className="fas fa-clock"></i>
                                                    <span>Expanding Soon</span>
                                                </div>
                                                <div className="coming-soon-list">
                                                    {comingSoonStations.map(([id, station]) => (
                                                        <div key={id} className="coming-soon-item" onClick={() => handleStationSelect(id)}>
                                                            <div className="station-name">
                                                                {station.station_info.name}
                                                                <span className="coming-soon-dot">🚧</span>
                                                            </div>
                                                            <div className="coming-soon-status">Soon</div>
                                                        </div>
                                                    ))}
                                                </div> */}
                                            </div>
                                            {!user && (
                                    <div className="login-section">
                                        <div className="login-card">
                                            <div className="login-icon">
                                                <i className="fas fa-user-circle"></i>
                                            </div>
                                            <h3>Personal Location Data</h3>
                                            <p>Login to view AQI data calculated for your exact location</p>
                                            <Link to="/login" className="login-cta-btn">
                                                <i className="fas fa-sign-in-alt"></i>
                                                Login to Access
                                            </Link>
                                        </div>
                                    </div>
                                )}
                                        </>
                                    )}
                                </div>
                            </div>
                        </div>
                        

                        {/* RIGHT PANEL - Optimized */}
                        <div className="details-panel">
                            <div className="panel-content">
                                {selectedStationData && !selectedStationData.is_coming_soon ? (
                                    <div className="station-details">
                                        {/* Station Header - Compact */}
                                        <div className="details-header">
                                            <div className="station-title">
                                                <h2>{selectedStationData.station_info.name}</h2>
                                                <div className="live-badge">🟢 LIVE DATA</div>
                                            </div>
                                            <div className="current-aqi">
                                                <span 
                                                    className="aqi-display"
                                                    style={{ backgroundColor: getAQIColor(selectedStationData.highest_sub_index) }}
                                                >
                                                    {Math.round(selectedStationData.highest_sub_index)}
                                                </span>
                                                <span className="aqi-status-text">
                                                    {getAQIStatus(selectedStationData.highest_sub_index)}
                                                </span>
                                            </div>
                                        </div>

                                        {/* Current Readings - Compact Grid */}
                                        <div className="readings-section">
                                            <h3><i className="fas fa-thermometer-half"></i> Current Readings</h3>
                                            <div className="readings-grid">
                                            {activePollutants.map(p => (
                                                <div className="reading-card" key={p.key}>
                                                    <div className="reading-label">{p.name}</div>
                                                    <div className="reading-value">
                                                        {getDisplayValue(p.key)}
                                                        <span className="reading-unit">{p.unit}</span>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                        </div>

                                        {/* Forecast Section - Compact */}
                                        <div className="forecast-section">
                                            <div className="forecast-header">
                                                <h3><i className="fas fa-chart-line"></i> 4-Day Forecast</h3>
                                                <select 
                                                    className="parameter-selector"
                                                    value={selectedParameter}
                                                    onChange={(e) => setSelectedParameter(e.target.value)}
                                                >
                                                    <option value="pm25_max">PM2.5</option>
                                                    <option value="pm10_max">PM10</option>
                                                    <option value="so2_max">SO₂</option>
                                                    <option value="no2_max">NO₂</option>
                                                    <option value="co_max">CO</option>
                                                    <option value="o3_max">O₃</option>
                                                    <option value="nh3_max">NH₃</option>
                                                </select>
                                            </div>
                                            
                                            <div className="chart-container">
                                                {isForecastLoading ? (
                                                    <div className="chart-loader">
                                                        <div className="loading-spinner"></div>
                                                        <p>Loading forecast...</p>
                                                    </div>
                                                ) : forecastData.length > 0 ? (
                                                    <Line data={forecastChartData} options={forecastChartOptions} />
                                                ) : (
                                                    <div className="no-data-message">
                                                        <i className="fas fa-chart-line"></i>
                                                        <p>No forecast data available</p>
                                                    </div>
                                                )}
                                                 {/* Login Prompt - Optimized */}
                                

                                            </div>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="no-selection">
                                        <div className="no-selection-content">
                                            <i className="fas fa-satellite-dish"></i>
                                            <h2>Select a Live Station</h2>
                                            <p>Choose a monitoring station from the sidebar to view real-time air quality data, current readings, and forecast information.</p>
                                            <div className="station-info-grid">
                                                <div className="info-item">
                                                    <span className="info-icon">🟢</span>
                                                    <span>Live stations provide real-time data</span>
                                                </div>
                                                <div className="info-item">
                                                    <span className="info-icon">🚧</span>
                                                    <span>More stations coming soon</span>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </>
                )}

                {/* Mobile Bottom Sheet - Optimized with Collapse Feature */}
                {isMobile && !isFullScreenMap && (
                    <div className={`mobile-bottom-sheet ${showMobileMenu ? 'open' : ''} ${isBottomSheetCollapsed ? 'collapsed' : ''}`}>
                        {/* Collapse/Expand Handle */}
                        <div className="bottom-sheet-handle" onClick={toggleBottomSheetCollapse}>
                            <div className="handle-bar"></div>
                            <div className="handle-text">
                                {isBottomSheetCollapsed ? 'Tap to expand' : 'Tap to minimize'}
                            </div>
                            <i className={`fas ${isBottomSheetCollapsed ? 'fa-chevron-up' : 'fa-chevron-down'} handle-icon`}></i>
                        </div>

                        {/* Mobile Tab Navigation */}
                        <div className="mobile-tab-nav">
                            <button 
                                className={`mobile-tab-btn ${activeTab === 'stations' ? 'active' : ''}`}
                                onClick={() => {
                                    setActiveTab('stations');
                                    setIsBottomSheetCollapsed(false);
                                }}
                            >
                                <i className="fas fa-broadcast-tower"></i>
                                <span>Stations</span>
                            </button>
                            <button 
                                className={`mobile-tab-btn ${activeTab === 'details' ? 'active' : ''}`}
                                onClick={() => {
                                    setActiveTab('details');
                                    setIsBottomSheetCollapsed(false);
                                }}
                            >
                                <i className="fas fa-chart-bar"></i>
                                <span>Details</span>
                            </button>
                            <button 
                                className={`mobile-tab-btn ${activeTab === 'user' ? 'active' : ''}`}
                                onClick={() => {
                                    setActiveTab('user');
                                    setIsBottomSheetCollapsed(false);
                                }}
                            >
                                <i className="fas fa-map-marker-alt"></i>
                                <span>My Data</span>
                            </button>
                        </div>

                        {/* Mobile Tab Content */}
                        <div className="mobile-tab-content-wrapper">
                            {renderMobileTabContent()}
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

export default MapPage;
